arguments.command:
cd /app && python - <<'E'
p='statements/meridale.py'
s=open(p).read()
a=s.index("def _amount")
new='''_LINKS = {
    "US/Pacific": "America/Los_Angeles", "US/Eastern": "America/New_York", "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata", "Asia/Saigon": "Asia/Ho_Chi_Minh", "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires", "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC", "GMT": "Etc/UTC",
}
_LOCALES = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}
_NBSP = "\\u00a0"
# locale: (decimal, group, code_before)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True), "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True), "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        if hours == 0:
            return "Etc/UTC"
        return f"Etc/GMT{'+' if m.group(1) == '-' else '-'}{hours}"
    return _LINKS.get(tz, tz)


def _locale(loc: str) -> str:
    loc = re.split(r"[.@]", loc)[0].replace("_", "-")
    if loc in _LOCALES:
        return loc
    lang = loc.split("-")[0]
    return lang if lang in _LOCALES else "en-US"


def _digits(currency: str) -> int:
    if currency in {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}:
        return 0
    if currency in {"BHD", "JOD", "KWD", "OMR", "TND"}:
        return 3
    return 2


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(intpart: str, indian: bool, spanish: bool, sep: str) -> str:
    if spanish and len(intpart) <= 4:
        return intpart
    if indian and len(intpart) > 3:
        head, tail = intpart[:-3], intpart[-3:]
        parts = []
        while len(head) > 2:
            parts.insert(0, head[-2:])
            head = head[:-2]
        if head:
            parts.insert(0, head)
        return sep.join(parts + [tail])
    parts = []
    while len(intpart) > 3:
        parts.insert(0, intpart[-3:])
        intpart = intpart[:-3]
    return sep.join([intpart] + parts)


def _format(value: Decimal, currency: str, loc: str, digits: int) -> str:
    dec, grp, before = _STYLE[loc]
    text = f"{abs(value):.{digits}f}"
    intpart, _, frac = text.partition(".")
    num = _group(intpart, loc == "en-IN", loc == "es", grp) + (dec + frac if digits else "")
    if value < 0:
        num = "-" + num
    return f"{currency}{_NBSP}{num}" if before else f"{num}{_NBSP}{currency}"


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    end = date(year + month // 12, month % 12 + 1, 1)
    loc = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": end.isoformat(),
        "locale": loc,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    cur = report["currency"]
    nd = _digits(cur)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_amount(d[k], nd) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _format(net, cur, loc, nd)))
    total = sum((line.net for line in lines), Decimal(0)).quantize(Decimal(1).scaleb(-nd))
    return Statement(merchant.id, cur, tuple(lines), total, _format(total, cur, loc, nd))
'''
s=s[:a]+new
s=s.replace("import json\n","import json\nimport re\n").replace("from decimal import Decimal","from decimal import ROUND_HALF_EVEN, Decimal")
open(p,'w').write(s)
E
sed -i 's/"USD 1,464.31"/"USD\\u00a01,464.31"/' tests/test_meridale.py
python -m unittest 2>&1|tail -3
echo '{"status":"success","summary":"Rewrote monthly_statement per current Meridale docs: canonical tz mapping, half-open range, locale param only, Decimal half-even rounding by currency digits, locale-aware text. Updated test for NBSP."}' > STATUS.json
